131	// Check if a value is only used by transpose ops whose users are all vector ops
132	bool DataDependencyAnalysisPass::isAllTransposedInVector(mlir::Value value) {
133	  if (!isa<linalg::MatmulOp>(value.getDefiningOp())) {
134	    return false;
135	  }
136	  if (!llvm::hasSingleElement(value.getUsers())) {
137	    return false;
138	  }
139	  auto *userOp = *value.getUsers().begin();
140	  if (!isa<linalg::TransposeOp>(userOp))
141	    return false;
142	  for (mlir::Operation *transposeOpUser : userOp->getUsers()) {
143	    if (getSsbufferCoreType(transposeOpUser) != ssbufferCoreTypeVectorAttr)
144	      return false;
145	  }
146	  return true;
147	}
148	
149	// Helper: Check if value is a valid tensor for dependency analysis
150	// Returns true if value is TensorType and not defined by EmptyOp/FillOp
151	bool DataDependencyAnalysisPass::isValidValueForDependency(mlir::Value value) {
152	  if (isValidScalarDependency(value)) {
153	    return true;
154	  }
155	  if (isValid1DValueForDependency(value)) {
156	    return true;
157	  }
158	  if (!isValidShapeForDependency(value)) {
159	    return false;
160	  }
161	
162	  Operation *defOp = value.getDefiningOp();
163	  // Op that can be processed both by CUBE and VECTOR should not be data
164	  // dependency
165	  if (defOp && isCubeOrVectorOp(defOp)) {
166	    return false;
167	  }
168	
169	  return true;
170	}
