494	// Analyze V->C
495	void DataDependencyAnalysisPass::analyzeExternalInputs(
496	    DataDependencyInfo &info) {
497	  auto &blockInfoMap = info.getBlockInfoMap();
498	  auto &v2cDependencies = info.getV2CDependencies();
499	
500	  LOG_DEBUG("Analyzing external inputs for Cube blocks...\n");
501	  for (auto &[id, blockInfo] : blockInfoMap) {
502	    if (!blockInfo.isCube || blockInfo.isControl || blockInfo.inputs.empty())
503	      continue;
504	    LOG_DEBUG("Analyzing external inputs for Cube Block ID: " << id << "\n");
505	    for (mlir::Value input : blockInfo.inputs) {
506	      // Check if input is a value which can be produced by CUBE
507	      if (!isValidValueForDependency(input)) {
508	        LOG_DEBUG("Warning: [v->c] Input value is not a valid tensor for "
509	                  "dependency analysis.\n");
510	        continue;
511	      }
512	      // Check if input is a blockarg.
513	      if (isOuterOpArg(input)) {
514	        LOG_DEBUG("Warning: [v->c] Input value is a function/scf parameter.\n");
515	        continue;
516	      }
517	
518	      Operation *defOp = input.getDefiningOp();
519	      auto defReuslt = dyn_cast<mlir::OpResult>(input);
520	      auto coreType = getCoreTypeWithIndex(
521	          defOp, defReuslt ? defReuslt.getResultNumber() : 0);
522	      if (coreType == "") {
523	        LOG_DEBUG("Warning: [v->c] Input value has no core type attribute.\n");
524	        continue;
525	      }
526	
527	      // Case 1: Cube -> C->C special case
528	      if (coreType == ssbufferCoreTypeCubeAttr) {
529	        continue;
530	      }
531	      // Case 2: Vector -> V->C dependency
532	      if (coreType == ssbufferCoreTypeVectorAttr) {
533	        LOG_DEBUG("Found external input with VECTOR core type: " << input
534	                                                                 << "\n");
535	        auto producerIdOpt = CVPipeline::getOpBlockId(input.getDefiningOp());
536	        if (!producerIdOpt) {
537	          LOG_DEBUG(
538	              "Warning: [v->c] Producer block ID not found for input value.\n");
539	          continue;
540	        }
541	        int producerId = *producerIdOpt;
542	        collectDepInfo(input, DependencyType::VectorToCube, v2cDependencies,
543	                       producerId, blockInfo.blockId, info);
544	      }
545	    }
546	  }
547	  LOG_DEBUG("External input analysis complete.\n");
548	}
549	
550	// Analyze C->V
551	void DataDependencyAnalysisPass::analyzeExternalOutputs(
552	    DataDependencyInfo &info) {
553	  auto &blockInfoMap = info.getBlockInfoMap();
554	  auto &c2vDependencies = info.getC2VDependencies();
555	
556	  LOG_DEBUG("Analyzing external outputs for Cube blocks...\n");
557	  for (auto &[id, blockInfo] : blockInfoMap) {
558	    if (!blockInfo.isCube || blockInfo.outputs.empty())
559	      continue;
560	
561	    for (mlir::Value output : blockInfo.outputs) {
562	      // Check if output is a value which can be produced by CUBE
563	      if (!isValidValueForDependency(output)) {
564	        LOG_DEBUG("Warning: [c->v] Output value is not a valid tensor for "
565	                  "dependency analysis.\n");
566	        continue;
567	      }
568	      if (isa<mlir::IntegerType, mlir::FloatType>(output.getType())) {
569	        LOG_DEBUG("Warning: [c->v] Output value is a scalar, not a valid "
570	                  "tensor for dependency analysis.\n");
571	        continue;
572	      }
573	
574	      auto opResult = dyn_cast<OpResult>(output);
575	      unsigned resultIndex = opResult.getResultNumber();
576	      StringRef resultCoreType =
577	          getCoreTypeWithIndex(output.getDefiningOp(), resultIndex);
578	      if (resultCoreType != ssbufferCoreTypeCubeAttr) {
579	        continue;
580	      }
581	
582	      // Check who is using this output
583	      llvm::DenseSet<int> handledBlockIds;
584	
585	      // if c->v value will be transposed and then used by vector op, the value
586	      // can be transposed within fixpipe
587	      bool isAllTranspoesd = isAllTransposedInVector(output);
588	
589	      for (mlir::Operation *user : output.getUsers()) {
590	        int outputIndex = 0;
591	        if (isControlFlowOp(user)) {
592	          for (unsigned i = 0; i < user->getNumOperands(); ++i) {
593	            if (user->getOperand(i) == output) {
594	              outputIndex = i;
595	              break;
596	            }
597	          }
598	        }
599	        auto userCoreType = getCoreTypeWithIndex(user, outputIndex);
600	        if ((userCoreType == "")) {
601	          LOG_DEBUG(
602	              "Warning: [c->v] Input value has no core type attribute.\n");
603	          continue;
604	        }
605	        if (userCoreType == ssbufferCoreTypeVectorAttr) {
606	          LOG_DEBUG("Found external output used by VECTOR core type: " << output
607	                                                                       << "\n");
608	          auto consumerIdOpt = CVPipeline::getOpBlockId(user);
609	          if (!consumerIdOpt) {
610	            LOG_DEBUG("Warning: [c->v] Consumer block ID not found for user "
611	                      "operation.\n");
612	            continue;
613	          }
614	          int consumerId = *consumerIdOpt;
615	          auto inserted = handledBlockIds.insert(consumerId).second;
616	          if (inserted) {
617	            collectDepInfo(output, DependencyType::CubeToVector,
618	                           c2vDependencies, blockInfo.blockId, consumerId, info,
619	                           isAllTranspoesd);
620	          }
621	        }
622	        // If user belongs to Cube block, this C->C dependency was handled
623	        // in the Input analysis phase, so here we only handle C->V.
624	      }
625	    }
626	  }
627	  LOG_DEBUG("External output analysis complete.\n");
628	}
