105	// Helper: parse OpCoreType from string (handles both "CUBE" and "CUBE,VECTOR"
106	// formats) For comma-separated multi-value strings, returns the i-th component
107	// if index is provided, otherwise returns the first component.
108	OpCoreType parseCoreTypeFromString(const std::string &coreTypeStr,
109	                                   size_t index = 0) {
110	  llvm::StringRef ref(coreTypeStr);
111	  llvm::SmallVector<llvm::StringRef, kMaxCoreTypeParts> parts;
112	  ref.split(parts, ',');
113	  if (parts.size() > 1 && index < parts.size()) {
114	    // Multi-value: pick i-th component
115	    return parseCoreTypeFromString(parts[index].str());
116	  }
117	  StringRef singleValue = parts[0].trim();
118	  if (singleValue == "CUBE") {
119	    return OP_CUBE_ONLY;
120	  } else if (singleValue == "VECTOR") {
121	    return OP_VECTOR_ONLY;
122	  } else if (singleValue == "CUBE_AND_VECTOR") {
123	    return OP_CUBE_AND_VECTOR;
124	  }
125	  return OP_UNDETERMINED;
126	}
