159	// ============================================================================
160	// Pattern: to_tensor → matmul (Upstream)
161	// ============================================================================
162	// Matches cases where matmul's input comes from bufferization.to_tensor.
163	// to_tensor converts a memref to a tensor, typically used for loading matrix
164	// data from memory. IR Example
165	//   %memref = memref.alloc() : memref<1024x1024xf32>
166	//   %tensor = bufferization.to_tensor %memref : memref<1024x1024xf32> ->
167	//   tensor<1024x1024xf32> %result = linalg.matmul ins(%tensor, %tensor_b)
168	//   outs(%init)
169	// Matching Logic
170	//   1. Check if matmul's operand defining op is bufferization.to_tensor
171	//   2. If matched, mark to_tensor as CUBE and add to cubeSeeds
172	//   3. Also trace back to_tensor's memref source and mark its defining op as
173	//   CUBE
174	// Purpose: Ensure matmul's input data loading executes on CUBE for efficient
175	// matrix data transfer.
176	// ============================================================================
177	void OpClassifierPass::matchToTensorPattern(Operation *def) {
178	  auto toTensorOp = dyn_cast<bufferization::ToTensorOp>(def);
179	  constexpr llvm::StringLiteral kMayImplicitTransposeWithLastAxis =
180	      "MayImplicitTransposeWithLastAxis";
181	
182	  if (!toTensorOp)
183	    return;
184	
185	  // special case: implicit transpose
186	  if (utils::getAnnotateOpWithAttr(toTensorOp.getResult(),
187	                                   kMayImplicitTransposeWithLastAxis)) {
188	    return;
189	  }
190	
191	  markCube(toTensorOp);
192	  cubeSeeds.push_back(toTensorOp);
193	
194	  // Also mark the memref allocation as CUBE
195	  Value memref = toTensorOp.getBuffer();
196	
197	  if (Operation *memrefDef = memref.getDefiningOp()) {
198	    markCube(memrefDef);
199	    cubeSeeds.push_back(memrefDef);
200	  }
201	}
202	
203	// ============================================================================
204	// Pattern: transpose → matmul (Upstream)
205	// ============================================================================
206	// Matches cases where matmul's input comes from linalg.transpose.
207	// transpose performs matrix transposition, commonly used as preprocessing for
208	// matrix multiplication inputs.
209	// IR Example
210	//   %input = tensor.empty() : tensor<1024x1024xf32>
211	//   %transposed = linalg.transpose ins(%input: tensor<1024x1024xf32>)
212	//   outs(%out: tensor<1024x1024xf32>)
213	//                   permutation = [1, 0]
214	//   %result = linalg.matmul ins(%transposed, %tensor_b) outs(%init)
215	// Matching Logic
216	//   1. Check if matmul's operand defining op is linalg.transpose
217	//   2. Mark transpose itself as CUBE (transpose operation is suitable for CUBE
218	//   execution)
219	//   3. Only mark transpose's input as CUBE seed when its operands come from
220	//      - bufferization dialect ops (e.g., to_tensor, clone), excluding
221	//      AllocTensorOp
222	//      - tensor.empty op
223	//   4. Check both transpose's operands and DpsInits (output initial values),
224	//   either one
225	//      satisfying the condition is sufficient
226	// Special Handling
227	//   When transpose's input comes from compute ops (e.g., arith.truncf),
228	//   transpose itself remains CUBE, but its upstream chain stays VECTOR to avoid
229	//   unnecessary CUBE expansion.
230	// Purpose: transpose is a common preprocessing op for matmul; executing on CUBE
231	// leverages matrix transfer capabilities.
232	// ============================================================================
233	void OpClassifierPass::matchTransposePattern(Operation *def) {
234	  auto transposeOp = dyn_cast<linalg::TransposeOp>(def);
235	  if (!transposeOp)
236	    return;
237	
238	  markCube(transposeOp);
239	
240	  // Helper lambda to check if an operand's defining op qualifies for CUBE seed
241	  auto shouldMarkCubeSeed = [](Operation *opDef) -> bool {
242	    if (!opDef)
243	      return false;
244	    return (isa<bufferization::BufferizationDialect>(opDef->getDialect()) &&
245	            !isa<bufferization::AllocTensorOp>(opDef)) ||
246	           isa<tensor::EmptyOp>(opDef);
247	  };
248	
249	  // Check input tensor
250	  auto operands = transposeOp->getOperands();
251	  for (const auto &op : operands) {
252	    if (shouldMarkCubeSeed(op.getDefiningOp())) {
253	      markCube(op.getDefiningOp());
254	      cubeSeeds.push_back(op.getDefiningOp());
255	      break; // No need to check other operands, one is enough to seed the
256	             // transpose as CUBE
257	    }
258	  }
259	
260	  // Check outs (DpsInits)
261	  auto outs = transposeOp.getDpsInits();
262	  for (const auto &out : outs) {
263	    if (shouldMarkCubeSeed(out.getDefiningOp())) {
264	      markCube(out.getDefiningOp());
265	      cubeSeeds.push_back(out.getDefiningOp());
266	      break;
267	    }
268	  }
269	}
270	
271	// ============================================================================
272	// Pattern: linalg.fill → matmul (Upstream)
273	// ============================================================================
274	// Matches cases where matmul's output initial value comes from linalg.fill.
275	// fill initializes the output matrix (typically to 0).
276	// IR Example
277	//   %value = arith.constant 0.0 : f32
278	//   %out = tensor.empty() : tensor<1024x1024xf32>
279	//   %init = linalg.fill ins(%value: f32) outs(%out: tensor<1024x1024xf32>)
280	//   %result = linalg.matmul ins(%a, %b) outs(%init)
281	// Matching Logic
282	//   1. Check if matmul's operand defining op is linalg.fill
283	//   2. If matched, mark fill as CUBE and add to cubeSeeds
284	// Purpose: fill operation initializes matmul's output buffer; executing on CUBE
285	// leverages efficient data filling capabilities.
286	// ============================================================================
287	void OpClassifierPass::matchFillPattern(Operation *def) {
288	  auto fillOp = dyn_cast<linalg::FillOp>(def);
289	  if (!fillOp)
290	    return;
291	
292	  markCube(fillOp);
293	  cubeSeeds.push_back(fillOp);
294	}
