296	// ============================================================================
297	// Pattern: tensor.empty → matmul (Upstream)
298	// ============================================================================
299	// Matches cases where matmul's output initial value comes from tensor.empty.
300	// empty initializes the output matrix (typically to 0).
301	// IR Example
302	//   %value = arith.constant 0.0 : f32
303	//   %out = tensor.empty() : tensor<1024x1024xf32>
304	//   %result = linalg.matmul ins(%a, %b) outs(%out)
305	// Matching Logic
306	//   1. Check if matmul's operand defining op is tensor.empty
307	//   2. If matched, mark empty as CUBE and add to cubeSeeds
308	// Purpose: empty operation initializes matmul's output buffer;
309	// ============================================================================
310	void OpClassifierPass::matchEmptyPattern(Operation *def) {
311	  auto emptyOp = dyn_cast<tensor::EmptyOp>(def);
312	  if (!emptyOp)
313	    return;
314	
315	  markCube(emptyOp);
316	  cubeSeeds.push_back(emptyOp);
317	}
318	
319	// ============================================================================
320	// Pattern: matmul → hivm.hir.store (Downstream)
321	// ============================================================================
322	// Matches cases where matmul's output is directly stored to memory.
323	// hivm.store is the HIVM dialect's store operation, writing tensor to memory.
324	// IR Example
325	//   %result = linalg.matmul ins(%a, %b) outs(%init)
326	//   hivm.store %result, %memref[%offset] : tensor<1024x1024xf32> to memref
327	// Matching Logic
328	//   1. Check if matmul result's user is hivm.store
329	//   2. If matched, mark store as CUBE and add to cubeSeeds
330	// Purpose: Ensure matmul result's store operation executes on CUBE for
331	// efficient matrix data write-back.
332	// ============================================================================
333	void OpClassifierPass::matchStorePattern(Operation *user) {
334	  if (!isa<hivm::StoreOp>(user))
335	    return;
336	
337	  markCube(user);
338	  cubeSeeds.push_back(user);
339	}
340	
341	// ============================================================================
342	// Pattern: matmul → tensor.extract_slice → hivm.store (Downstream)
343	// ============================================================================
344	// Matches cases where matmul's output is sliced before being stored.
345	// extract_slice extracts a sub-region (slice) of a tensor, commonly used after
346	// tiled matrix computation for result extraction.
347	// IR Example
348	//   %result = linalg.matmul ins(%a, %b) outs(%init) : tensor<1024x1024xf32>
349	//   %slice = tensor.extract_slice %result[0, 0][256, 256][1, 1] :
350	//   tensor<1024x1024xf32> to tensor<256x256xf32> hivm.store %slice,
351	//   %memref[%offset] : tensor<256x256xf32> to memref
352	// Matching Logic
353	//   1. Check if matmul result's user is tensor.extract_slice
354	//   2. If matched, mark extract_slice as CUBE and add to cubeSeeds
355	//   3. Further check all users of extract_slice and mark hivm.store as CUBE
356	// Purpose: After tiled matrix computation, slice and store operations on CUBE
357	// improve local data transfer efficiency.
358	// ============================================================================
359	void OpClassifierPass::matchExtractSlicePattern(Operation *user) {
360	  auto extractSliceOp = dyn_cast<tensor::ExtractSliceOp>(user);
361	  if (!extractSliceOp)
362	    return;
363	
364	  markCube(extractSliceOp);
365	  cubeSeeds.push_back(extractSliceOp);
366	  // Also mark downstream hivm.hir.store as CUBE
367	  for (Operation *sliceUser : extractSliceOp->getUsers()) {
368	    if (isa<hivm::StoreOp>(sliceUser) ||
369	        isa<bufferization::MaterializeInDestinationOp>(sliceUser)) {
370	      markCube(sliceUser);
371	      cubeSeeds.push_back(sliceUser);
372	    }
373	  }
374	}
375	
376	// ============================================================================
377	// Pattern: matmul → materialize_in_destination (Downstream)
378	// ============================================================================
379	// Matches cases where matmul's output is written to a destination buffer via
380	// materialize_in_destination. This operation materializes tensor results into a
381	// pre-allocated destination location.
382	// IR Example
383	//   %result = linalg.matmul ins(%a, %b) outs(%init) : tensor<1024x1024xf32>
384	//   %memref = memref.alloc() : memref<1024x1024xf32>
385	//   bufferization.materialize_in_destination %result in %memref
386	//     : tensor<1024x1024xf32> to memref<1024x1024xf32>
387	// Matching Logic
388	//   1. Check if matmul result's user is
389	//   bufferization.materialize_in_destination
390	//   2. If matched, mark it as CUBE and add to cubeSeeds
391	// Purpose: matmul result materialization on CUBE leverages efficient matrix
392	// data transfer capabilities.
393	// ============================================================================
394	void OpClassifierPass::matchMaterializePattern(Operation *user) {
395	  if (!isa<bufferization::MaterializeInDestinationOp>(user))
396	    return;
397	
398	  markCube(user);
399	  cubeSeeds.push_back(user);
400	}
