402	static bool allResultHasOneUser(Operation *op) {
403	  bool ret = true;
404	  for (Value result : op->getResults()) {
405	    if (!result.hasOneUse()) {
406	      ret = false;
407	      break;
408	    }
409	  }
410	  return ret;
411	}
