413	// Pattern matching for CUBE operations
414	int OpClassifierPass::patternMatchCUBE() {
415	  LOG_DEBUG("--- Step 1: pattern match --->\n");
416	
417	  for (Operation *op : allOps) {
418	    if (!isa<linalg::MatmulOp>(op))
419	      continue;
420	
421	    // matmul always CUBE
422	    opCoreTypes[op] = OP_CUBE_ONLY;
423	    LLVM_DEBUG(DBGS() << "CUBE (matmul): " << *op << "\n");
424	
425	    // ---- Upstream pattern matching ----
426	    for (Value operand : op->getOperands()) {
427	      Operation *def = operand.getDefiningOp();
428	      // A null defining op means `operand` is a loop iter_arg block argument.
429	      // Walk back to its init operand (repeating to also cross nested loops).
430	      for (Value cur = operand; !def;) {
431	        auto blockArg = dyn_cast<BlockArgument>(cur);
432	        auto loopLike = blockArg ? dyn_cast_or_null<LoopLikeOpInterface>(
433	                                       blockArg.getOwner()->getParentOp())
434	                                 : nullptr;
435	        OpOperand *init =
436	            loopLike ? loopLike.getTiedLoopInit(blockArg) : nullptr;
437	        if (!init) {
438	          break;
439	        }
440	        cur = init->get();
441	        def = cur.getDefiningOp();
442	      }
443	      if (!def)
444	        continue;
445	
446	      matchToTensorPattern(def);
447	      matchTransposePattern(def);
448	      matchFillPattern(def);
449	      matchEmptyPattern(def);
450	    }
451	
452	    // ---- Downstream pattern matching ----
453	    for (Value result : op->getResults()) {
454	      if (!result.hasOneUse()) {
455	        continue;
456	      }
457	      for (Operation *user : result.getUsers()) {
458	        // If user is scf.yield, follow the chain to find real users
459	        Operation *curUser = user;
460	        Value prevResult = result;
461	        while (curUser) {
462	          if (!allResultHasOneUser(curUser)) {
463	            break;
464	          }
465	          if (auto yieldOp = dyn_cast<scf::YieldOp>(curUser)) {
466	            if (Operation *scfOp = yieldOp->getParentOp()) {
467	              // Find which operand index the previous result corresponds to in
468	              // the yield
469	              unsigned yieldOperandIdx = 0;
470	              for (unsigned i = 0; i < yieldOp->getNumOperands(); ++i) {
471	                if (yieldOp->getOperand(i) == prevResult) {
472	                  yieldOperandIdx = i;
473	                  break;
474	                }
475	              }
476	              // Get the corresponding scf result
477	              if (yieldOperandIdx < scfOp->getNumResults()) {
478	                Value scfResult = scfOp->getResult(yieldOperandIdx);
479	                prevResult = scfResult;
480	                // Find the next user (skipping yield)
481	                curUser = nullptr;
482	                for (Operation *nextUser : scfResult.getUsers()) {
483	                  if (!isa<scf::YieldOp>(nextUser)) {
484	                    curUser = nextUser;
485	                    break;
486	                  }
487	                }
488	                // If no non-yield user found, continue searching from yield
489	                if (!curUser) {
490	                  for (Operation *nextUser : scfResult.getUsers()) {
491	                    if (isa<scf::YieldOp>(nextUser)) {
492	                      curUser = nextUser;
493	                      break;
494	                    }
495	                  }
496	                }
497	                continue;
498	              }
499	            }
500	            break;
501	          }
502	          matchStorePattern(curUser);
503	          matchExtractSlicePattern(curUser);
504	          matchMaterializePattern(curUser);
505	          break;
506	        }
507	      }
508	    }
509	  }
510	
511	  LLVM_DEBUG(DBGS() << "seeds: " << cubeSeeds.size() << " to_tensor(s)\n");
512	  for (Operation *seed : cubeSeeds) {
513	    LLVM_DEBUG(DBGS() << "CUBE: " << *seed << "\n");
514	  }
515	
516	  return 0;
517	}
