524	// Helper: Check if a value is a scalar iter_arg from scf.for
525	// An iter_arg is a BlockArgument of scf.for's loop body, and it must be scalar
526	// type
527	static bool isScalarIterArgOp(Value iterArg) {
528	  // iter_arg is a BlockArgument of scf.for's body
529	  auto blockArg = dyn_cast<BlockArgument>(iterArg);
530	  if (!blockArg)
531	    return false;
532	  // Check if parent is scf.for
533	  Operation *parentOp = blockArg.getOwner()->getParentOp();
534	  if (!isa<scf::ForOp>(parentOp))
535	    return false;
536	  // Check if the iter_arg is scalar type (not tensor)
537	  return isScalarType(iterArg);
538	}
