540	// Helper: Find iter_arg initialization op and yield-assigning op for scf.for
541	// loop-carried scalar When a def comes from an scf.for iter_arg and is a scalar
542	// compute op, we need to:
543	// 1. Find the iter_arg's initialization op (the op that provides the initial
544	// value)
545	// 2. Find the yieldOp, then trace to the op that provides the yielded value
546	// All found ops are added to upstreamOps
547	static void
548	findIterArgUpstreamOps(Value def,
549	                       llvm::SmallVectorImpl<Operation *> &upstreamOps) {
550	  // Check if def is a block argument (iter_arg)
551	  auto blockArg = dyn_cast<BlockArgument>(def);
552	  if (!blockArg)
553	    return;
554	
555	  // Check if parent is scf.for
556	  Operation *parentOp = blockArg.getOwner()->getParentOp();
557	  auto forOp = dyn_cast<scf::ForOp>(parentOp);
558	  if (!forOp)
559	    return;
560	
561	  // Get the iter_arg index from block argument
562	  unsigned argIdx = blockArg.getArgNumber();
563	
564	  // Get the iter_arg and check its type - must be scalar (not tensor)
565	  // The init value is at forOp.getInitArgs()[argIdx]
566	  if (argIdx > forOp.getInitArgs().size() || argIdx == 0)
567	    return;
568	  Value initValue = forOp.getInitArgs()[argIdx - 1];
569	  if (!isScalarType(initValue))
570	    return;
571	
572	  // Find the initialization op for this iter_arg
573	  Operation *initDef = initValue.getDefiningOp();
574	  if (initDef && initDef != forOp) {
575	    LLVM_DEBUG(DBGS() << "[findIterArgUpstreamOps] init def: " << *initDef
576	                      << "\n");
577	    upstreamOps.push_back(initDef);
578	  }
579	
580	  // Find the yieldOp and the op that provides the yielded value
581	  // The yieldOp has operands corresponding to the iteration results
582	  // For iter_arg i, yieldOp.getOperand(i) is the value yielded for that
583	  // iter_arg
584	  Operation *yieldOp = forOp.getBody()->getTerminator();
585	  if (!isa<scf::YieldOp>(yieldOp) || argIdx > yieldOp->getNumOperands())
586	    return;
587	
588	  Value yieldedValue = yieldOp->getOperand(argIdx - 1);
589	  Operation *yieldedDef = yieldedValue.getDefiningOp();
590	  if (yieldedDef && yieldedDef != forOp) {
591	    LLVM_DEBUG(DBGS() << "[findIterArgUpstreamOps] yielded def: " << *yieldedDef
592	                      << "\n");
593	    upstreamOps.push_back(yieldedDef);
594	  }
595	}
