597	// Helper function to get upstream operations based on both SSA and memory
598	// dependencies
599	void OpClassifierPass::getUpstreamOpsWithMemoryDeps(
600	    Operation *cur, llvm::SmallVectorImpl<Operation *> &upstreamOps) {
601	  // Collect SSA dependencies (direct operands)
602	  for (Value operand : cur->getOperands()) {
603	    Operation *def = operand.getDefiningOp();
604	    if (def && def != cur) {
605	      // Check if this def is an scf.for iter_arg that is a scalar
606	      LLVM_DEBUG(DBGS() << "push op: " << *def << "\n");
607	      upstreamOps.push_back(def);
608	    }
609	    if (isScalarIterArgOp(operand)) {
610	      findIterArgUpstreamOps(operand, upstreamOps);
611	    }
612	  }
613	  if (!isa<bufferization::ToTensorOp>(cur)) {
614	    // Only consider memory dependencies for non-to_tensor ops,
615	    // as to_tensor already has SSA deps to its memref source
616	    return;
617	  }
618	  // Collect memory dependencies
619	  if (memDepGraph) {
620	    // Get operations that define memory used by current op
621	    for (Operation *memDef : memDepGraph->getMemDefs(cur)) {
622	      LLVM_DEBUG(DBGS() << "memDef: cur " << *cur << " -> memDef " << *memDef
623	                        << "\n");
624	      if (isa<memref::CopyOp>(memDef)) {
625	        LLVM_DEBUG(DBGS() << "push op: " << *memDef << "\n");
626	        upstreamOps.push_back(memDef);
627	      }
628	    }
629	  }
630	}
