632	// Propagate CUBE core type upstream
633	int OpClassifierPass::propagateCubeUpstream() {
634	  LLVM_DEBUG(DBGS() << "--- Step 2: CUBE upstream BFS --->\n");
635	  llvm::DenseSet<Operation *> cubeVisited;
636	  std::queue<Operation *> cubeQueue;
637	
638	  for (Operation *seed : cubeSeeds) {
639	    cubeVisited.insert(seed);
640	    cubeQueue.push(seed);
641	  }
642	
643	  while (!cubeQueue.empty()) {
644	    Operation *cur = cubeQueue.front();
645	    cubeQueue.pop();
646	    LLVM_DEBUG(DBGS() << "cur: " << *cur << "\n");
647	
648	    // Get upstream operations considering both SSA and memory dependencies
649	    llvm::SmallVector<Operation *> upstreamOps;
650	    getUpstreamOpsWithMemoryDeps(cur, upstreamOps);
651	
652	    for (Operation *def : upstreamOps) {
653	      if (!def || cubeVisited.count(def) || isa<linalg::MatmulOp>(def))
654	        continue;
655	
656	      // Skip arith dialect ops with tensor results (they should be VECTOR, not
657	      // CUBE)
658	      if (isa<arith::ArithDialect>(def->getDialect())) {
659	        bool hasTensorResult = false;
660	        for (Value result : def->getResults()) {
661	          if (isa<RankedTensorType>(result.getType())) {
662	            hasTensorResult = true;
663	            break;
664	          }
665	        }
666	        if (hasTensorResult) {
667	          LLVM_DEBUG(DBGS() << "skip " << def->getName().getStringRef()
668	                            << ": arith tensor op\n");
669	          continue;
670	        }
671	      }
672	
673	      // Skip operations inside linalg block (internal values)
674	      // But don't skip the linalg op itself
675	      if (isInsideNestedLinalgRegion(def)) {
676	        LLVM_DEBUG(DBGS() << "skip " << def->getName().getStringRef()
677	                          << ": inside linalg block\n");
678	        continue;
679	      }
680	
681	      cubeVisited.insert(def);
682	
683	      LLVM_DEBUG(DBGS() << "\tcolor-cube: " << def->getName().getStringRef()
684	                        << "\n");
685	      opCoreTypes[def] = OP_CUBE_ONLY;
686	      cubeQueue.push(def);
687	    }
688	  }
689	
690	  // Handle fill ops: mark as CUBE only if linalg.fill output buffer is CUBE
691	  markFillOpsAsCube();
692	
693	  return 0;
694	}
695	
696	// ============================================================================
697	// Step 3: Mark remaining operations as VECTOR
698	// ============================================================================
699	// After Step 2 (CUBE propagation), any operation still marked as UNDETERMINED
700	// is classified as VECTOR. This establishes the default that non-CUBE
701	// operations should execute on the VECTOR core.
702	// ============================================================================
703	int OpClassifierPass::markRemainingAsVector() {
704	  LLVM_DEBUG(DBGS() << "--- Step 3: default VECTOR --->\n");
705	  for (Operation *op : allOps) {
706	    if (isa<annotation::MarkOp>(op)) {
707	      auto markOp = cast<annotation::MarkOp>(op);
708	      Value src = markOp.getSrc();
709	      if (Operation *srcDef = src.getDefiningOp()) {
710	        opCoreTypes[op] = getCoreType(srcDef);
711	      } else {
712	        opCoreTypes[op] = OP_VECTOR_ONLY;
713	      }
714	      continue;
715	    }
716	
717	    if (opCoreTypes[op] == OP_UNDETERMINED && !isa<scf::YieldOp>(op)) {
718	      opCoreTypes[op] = OP_VECTOR_ONLY;
719	    }
720	  }
721	
722	  return 0;
723	}
