725	// ============================================================================
726	// Helper: Mark fill operations as CUBE when their output buffer is CUBE
727	// ============================================================================
728	// This function handles a special case where linalg.fill's result feeds into
729	// a CUBE operation. In such cases, the fill itself should be marked CUBE.
730	// Case 1: fill's outs operand is defined by a CUBE_ONLY operation (not
731	// tensor.empty)
732	//   IR example
733	//     %empty = tensor.empty() : tensor<1024x1024xf32>  // CUBE
734	//     %filled = linalg.fill ins(%value) outs(%empty)   // should be CUBE
735	//   Here %filled's outs comes from a CUBE op, so fill is CUBE
736	// Case 2: fill's outs is a BlockArgument (scf.for/scf.if iter_arg) that is CUBE
737	//   IR example
738	//     scf.for ... iter_args(%arg = %filled) {  // %arg is CUBE
739	//       ...
740	//     }
741	//   Here the iter_arg is CUBE, so fill is CUBE
742	// ============================================================================
743	void OpClassifierPass::markFillOpsAsCube() {
744	  LLVM_DEBUG(DBGS() << "--- Marking fill ops as CUBE when outs is CUBE --->\n");
745	
746	  for (Operation *op : allOps) {
747	    // Only process fill ops that are still UNDETERMINED
748	    if (!isa<linalg::FillOp>(op) || opCoreTypes[op] != OP_UNDETERMINED) {
749	      continue;
750	    }
751	
752	    auto fillOp = cast<linalg::FillOp>(op);
753	    Value outs = fillOp.getDpsInits()[0];
754	    Operation *outsDef = outs.getDefiningOp();
755	
756	    bool outsIsCube = false;
757	
758	    // Case 1: outs is defined by a CUBE_ONLY operation (not tensor.empty)
759	    // tensor.empty is a special case - it doesn't determine CUBE/VECTOR
760	    if (outsDef && opCoreTypes[outsDef] == OP_CUBE_ONLY &&
761	        !isa<tensor::EmptyOp>(outsDef)) {
762	      outsIsCube = true;
763	      LLVM_DEBUG(DBGS() << "\tfill outs defined by CUBE op: "
764	                        << outsDef->getName().getStringRef() << "\n");
765	    } else if (!outsDef) { // Case 2: outs is a BlockArgument (scf.for/scf.if
766	                           // iter_arg)
767	      auto blockArg = dyn_cast<BlockArgument>(outs);
768	      if (blockArg) {
769	        Operation *parentOp = blockArg.getOwner()->getParentOp();
770	        // Check if it's an scf.for or scf.if iter_arg that is CUBE
771	        if ((isa<scf::ForOp>(parentOp) || isa<scf::IfOp>(parentOp)) &&
772	            opCoreTypes[parentOp] == OP_CUBE_ONLY) {
773	          outsIsCube = true;
774	          LLVM_DEBUG(DBGS() << "\tfill outs is CUBE iter_arg of: "
775	                            << parentOp->getName().getStringRef() << "\n");
776	        }
777	      }
778	    }
779	
780	    if (outsIsCube) {
781	      LLVM_DEBUG(DBGS() << "\tfill-cube (outs is CUBE): " << *op << "\n");
782	      opCoreTypes[op] = OP_CUBE_ONLY;
783	    }
784	
785	    // Case 3: handle fill op in scf.if with all CUBE ops, Vector ops are
786	    // automatically marked as vector.
787	    handleFillInScfIf(op);
788	  }
789	}
