791	// Helper: Handle fill op in scf.if - if all ops in scf.if are CUBE, mark scf.if
792	// and propagate upstream
793	void OpClassifierPass::handleFillInScfIf(Operation *fillOp) {
794	  Operation *parentOp = fillOp->getParentOp();
795	  auto ifOp = dyn_cast<scf::IfOp>(parentOp);
796	  if (!ifOp)
797	    return;
798	
799	  // Only handle scf.if used for conditional branching (no iter_args)
800	  // If scf.if has results (iter_args), it's used as a loop structure, skip it
801	  if (!ifOp.getResults().empty())
802	    return;
803	
804	  // Check if all ops in scf.if's blocks are CUBE (except yield terminator)
805	  bool allOpsAreCube = true;
806	  for (Region &region : ifOp->getRegions()) {
807	    for (Block &block : region) {
808	      for (Operation &innerOp : block.getOperations()) {
809	        if (isa<scf::YieldOp>(innerOp))
810	          continue;
811	        // Check if this op is marked as CUBE
812	        if (opCoreTypes[&innerOp] != OP_CUBE_ONLY) {
813	          allOpsAreCube = false;
814	          break;
815	        }
816	      }
817	      if (!allOpsAreCube)
818	        break;
819	    }
820	    if (!allOpsAreCube)
821	      break;
822	  }
823	
824	  if (allOpsAreCube) {
825	    LLVM_DEBUG(
826	        DBGS() << "\tfill in scf.if with all CUBE ops, mark scf.if as CUBE: "
827	               << *ifOp << "\n");
828	    opCoreTypes[ifOp] = OP_CUBE_ONLY;
829	    // Propagate CUBE upstream for the scf.if
830	    propagateCubeUpstreamForOp(ifOp);
831	  }
832	}
833	
834	// Helper: Propagate CUBE core type upstream for a given operation
835	void OpClassifierPass::propagateCubeUpstreamForOp(Operation *startOp) {
836	  std::queue<Operation *> cubeQueue;
837	  llvm::DenseSet<Operation *> cubeVisited;
838	  cubeVisited.insert(startOp);
839	  cubeQueue.push(startOp);
840	
841	  while (!cubeQueue.empty()) {
842	    Operation *cur = cubeQueue.front();
843	    cubeQueue.pop();
844	
845	    // Get upstream operations
846	    llvm::SmallVector<Operation *> upstreamOps;
847	    getUpstreamOpsWithMemoryDeps(cur, upstreamOps);
848	
849	    for (Operation *upstreamOp : upstreamOps) {
850	      if (!upstreamOp || cubeVisited.count(upstreamOp))
851	        continue;
852	      if (isa<linalg::MatmulOp>(upstreamOp))
853	        continue;
854	
855	      cubeVisited.insert(upstreamOp);
856	      LLVM_DEBUG(DBGS() << "\t\tcube upstream: "
857	                        << upstreamOp->getName().getStringRef() << "\n");
858	      opCoreTypes[upstreamOp] = OP_CUBE_ONLY;
859	      cubeQueue.push(upstreamOp);
860	    }
861	  }
862	}
863	
864	// ============================================================================
865	// Step 4: Propagate VECTOR core type upstream
866	// ============================================================================
867	// After Step 3, propagate VECTOR classification to upstream operations.
868	// BFS traversal from all VECTOR operations, marking their upstream dependencies
869	// as VECTOR unless they are CUBE-only operations (e.g., matmul).
870	// Skips builtin.module and func.func operations.
871	// ============================================================================
872	int OpClassifierPass::propagateVectorUpstream() {
873	  LLVM_DEBUG(DBGS() << "--- Step 4: VECTOR upstream BFS --->\n");
874	  llvm::DenseSet<Operation *> vecVisited;
875	  std::queue<Operation *> vecQueue;
876	
877	  for (Operation *op : allOps) {
878	    if (opCoreTypes[op] == OP_VECTOR_ONLY) {
879	      vecVisited.insert(op);
880	      vecQueue.push(op);
881	    }
882	  }
883	
884	  while (!vecQueue.empty()) {
885	    Operation *cur = vecQueue.front();
886	    vecQueue.pop();
887	    // Skip builtin.module, func.func, and func.return operations
888	    if (isa<ModuleOp, func::FuncOp, func::ReturnOp>(cur) ||
889	        (isa<memref::CopyOp, memref::AllocaOp>(cur) &&
890	         opCoreTypes[cur] == OP_CUBE_ONLY)) {
891	      continue;
892	    }
893	    LLVM_DEBUG(DBGS() << "vec-def: " << *cur << "\n");
894	
895	    // Get upstream operations considering both SSA and memory dependencies
896	    llvm::SmallVector<Operation *> upstreamOps;
897	    getUpstreamOpsWithMemoryDeps(cur, upstreamOps);
898	
899	    for (Operation *def : upstreamOps) {
900	      if (!def || vecVisited.count(def))
901	        continue;
902	
903	      // Skip operations that should not be marked VECTOR:
904	      // - matmul: never mark matmul as vector (CUBE-only operation)
905	      if (isa<linalg::MatmulOp>(def) ||
906	          isa<scf::SCFDialect>(def->getDialect())) {
907	        LLVM_DEBUG(DBGS() << "skip " << def->getName().getStringRef()
908	                          << ": should not be marked VECTOR\n");
909	        continue;
910	      }
911	
912	      vecVisited.insert(def);
913	
914	      LLVM_DEBUG(DBGS() << "\tcolor-vec: " << def->getName().getStringRef()
915	                        << "\n");
916	      opCoreTypes[def] =
917	          static_cast<OpCoreType>(opCoreTypes[def] | OP_VECTOR_ONLY);
918	      vecQueue.push(def);
919	    }
920	  }
921	
922	  return 0;
923	}
