927	// A loader loop may only contain data-movement and (scalar) index computation.
928	// Any tensor-producing compute op means the loop does real vector work and must
929	// not be swallowed into the cube pipe.
930	bool isDisqualifyingLoaderOp(Operation *op) {
931	  if (isa<linalg::MatmulOp, linalg::ReduceOp, linalg::BroadcastOp,
932	          linalg::GenericOp, linalg::MapOp>(op)) {
933	    return true;
934	  }
935	  if (isa<math::MathDialect>(op->getDialect())) {
936	    return true;
937	  }
938	  // Elementwise arith on tensors is vector compute; scalar index math is fine.
939	  if (isa<arith::ArithDialect>(op->getDialect())) {
940	    for (Value result : op->getResults()) {
941	      if (isa<RankedTensorType>(result.getType())) {
942	        return true;
943	      }
944	    }
945	  }
946	  return false;
947	}
948	
949	} // namespace
950	
951	bool OpClassifierPass::isCubeLoaderForOp(scf::ForOp forOp) {
952	  // Every result must be live and used only by CUBE consumers. A single
953	  // non-cube (or scf.yield) user disqualifies the loop.
954	  bool hasCubeConsumer = false;
955	  for (Value result : forOp.getResults()) {
956	    for (Operation *user : result.getUsers()) {
957	      if (isa<linalg::MatmulOp>(user) || getCoreType(user) == OP_CUBE_ONLY) {
958	        hasCubeConsumer = true;
959	        continue;
960	      }
961	      return false;
962	    }
963	  }
964	  if (!hasCubeConsumer) {
965	    return false;
966	  }
967	
968	  // The body (including nested regions) must be pure data movement.
969	  bool disqualified = false;
970	  forOp.getBody()->walk([&](Operation *op) {
971	    if (op == forOp.getOperation()) {
972	      return WalkResult::advance();
973	    }
974	    if (isDisqualifyingLoaderOp(op)) {
975	      disqualified = true;
976	      return WalkResult::interrupt();
977	    }
978	    return WalkResult::advance();
979	  });
980	  return !disqualified;
981	}
982	
983	int OpClassifierPass::penetrateCubeIntoForLoops() {
984	  // Collect first so recoloring earlier loops cannot perturb the scan.
985	  llvm::SmallVector<scf::ForOp> loaderLoops;
986	  getOperation().walk([&](scf::ForOp forOp) {
987	    if (isCubeLoaderForOp(forOp)) {
988	      loaderLoops.push_back(forOp);
989	    }
990	  });
991	
992	  for (scf::ForOp forOp : loaderLoops) {
993	    // Set core_type to OP_CUBE_ONLY for scf.for.
994	    forOp.getBody()->walk([&](Operation *op) {
995	      if (op == forOp.getOperation() ||
996	          isa<scf::SCFDialect>(op->getDialect())) {
997	        return;
998	      }
999	      auto it = opCoreTypes.find(op);
1000	      if (it != opCoreTypes.end()) {
1001	        it->second = OP_CUBE_ONLY;
1002	      }
1003	    });
1004	    opCoreTypes[forOp] = OP_CUBE_ONLY;
1005	  }
1006	
1007	  return 0;
1008	}
