1041	
1042	bool OpClassifierPass::shouldStopPropagationForYield(
1043	    Operation *op, OpCoreType targetCoreType) {
1044	  // Stop at linalg.matmul
1045	  if (isa<linalg::MatmulOp>(op)) {
1046	    return true;
1047	  }
1048	
1049	  // Stop at hivm.hir.store
1050	  if (isa<hivm::StoreOp>(op)) {
1051	    return true;
1052	  }
1053	
1054	  // Stop at tensor-type operations that are already VECTOR_ONLY when targeting
1055	  // CUBE
1056	  if (targetCoreType == OP_CUBE_ONLY) {
1057	    if (op->getNumResults() > 0) {
1058	      for (Value result : op->getResults()) {
1059	        if (isa<TensorType>(result.getType())) {
1060	          OpCoreType currentType = getCoreType(op);
1061	          if (currentType == OP_VECTOR_ONLY) {
1062	            return true;
1063	          }
1064	        }
1065	      }
1066	    }
1067	  }
1068	
1069	  // Stop at scf dialect operations
1070	  if (isa<scf::SCFDialect>(op->getDialect())) {
1071	    return true;
1072	  }
1073	
1074	  // Stop at func.func or builtin.module
1075	  if (isa<func::FuncOp, ModuleOp>(op)) {
1076	    return true;
1077	  }
1078	
1079	  return false;
1080	}
1081	
1082	void OpClassifierPass::propagateCoreTypeUpwardForYield(
1083	    Operation *startOp, OpCoreType targetCoreType) {
1084	  if (!startOp)
1085	    return;
1086	
1087	  llvm::DenseSet<Operation *> visited;
1088	  std::queue<Operation *> queue;
1089	  queue.push(startOp);
1090	  visited.insert(startOp);
1091	
1092	  while (!queue.empty()) {
1093	    Operation *cur = queue.front();
1094	    queue.pop();
1095	
1096	    if (!cur || !cur->getBlock())
1097	      continue;
1098	
1099	    if (shouldStopPropagationForYield(cur, targetCoreType))
1100	      continue;
1101	
1102	    opCoreTypes[cur] = targetCoreType;
1103	
1104	    // Propagate to operands (upstream)
1105	    for (Value operand : cur->getOperands()) {
1106	      if (Operation *defOp = operand.getDefiningOp()) {
1107	        if (!visited.count(defOp) && defOp != cur) {
1108	          visited.insert(defOp);
1109	          queue.push(defOp);
1110	        }
1111	      }
1112	    }
1113	
1114	    // Also propagate to memory dependencies
1115	    if (memDepGraph) {
1116	      for (Operation *memDef : memDepGraph->getMemDefs(cur)) {
1117	        if (!visited.count(memDef) && memDef != cur) {
1118	          visited.insert(memDef);
1119	          queue.push(memDef);
1120	        }
1121	      }
1122	    }
1123	  }
1124	}
