1126	// handleYieldFromElseRegion: Extracts core_type from then region yield for else
1127	// region processing. For scf.if with else region, when processing the else
1128	// region's yield terminator, we need to use the then region's yield's core_type
1129	// attribute as the authoritative source. If the then yield has a
1130	// comma-separated multi-value type string (e.g., "CUBE,VECTOR"), this function
1131	// extracts the i-th component for the operand at index i.
1132	// Parameters
1133	//   - coreTypes: Vector to append the extracted core type to
1134	//   - operandIndex: Index of the operand in the yield (for extracting
1135	//   multi-value types)
1136	//   - thenYieldForElse: The then region's yield operation (from scf.if)
1137	//   - operand: The current operand value from the else region's yield
1138	// Returns: true if core_type was successfully extracted and propagated, false
1139	// otherwise.
1140	bool OpClassifierPass::handleYieldFromElseRegion(
1141	    std::vector<OpCoreType> &coreTypes, unsigned operandIndex,
1142	    Operation *thenYieldForElse, Value &operand, Operation *elseYieldOp) {
1143	  // Only handle if thenYieldForElse is provided and is a scf.yield
1144	  if (!thenYieldForElse || !isa<scf::YieldOp>(thenYieldForElse)) {
1145	    return false;
1146	  }
1147	
1148	  // Get the core_type attribute from then region yield
1149	  auto thenCoreTypeAttr = thenYieldForElse->getAttr("ssbuffer.core_type");
1150	  if (!thenCoreTypeAttr) {
1151	    return false;
1152	  }
1153	
1154	  StringAttr thenCoreTypeStrAttr = dyn_cast<StringAttr>(thenCoreTypeAttr);
1155	  if (!thenCoreTypeStrAttr) {
1156	    return false;
1157	  }
1158	
1159	  // Extract the i-th component from comma-separated core type string
1160	  std::string thenCoreTypeStr = thenCoreTypeStrAttr.getValue().str();
1161	  OpCoreType coreTypeToUse =
1162	      parseCoreTypeFromString(thenCoreTypeStr, operandIndex);
1163	  coreTypes.push_back(coreTypeToUse);
1164	
1165	  // Propagate the determined core_type upstream to the defining operation
1166	  if (Operation *defOp = operand.getDefiningOp()) {
1167	    if (CloneOpMap.count(defOp) && opCoreTypes.count(defOp) &&
1168	        opCoreTypes[defOp] != coreTypeToUse) {
1169	      Operation *cloneOp = CloneOpMap[defOp];
1170	      // Replace the operand in else yield with the cloneOp's result
1171	      for (unsigned i = 0; i < defOp->getNumResults(); ++i) {
1172	        if (defOp->getResult(i) == operand) {
1173	          elseYieldOp->setOperand(operandIndex, cloneOp->getResult(i));
1174	          defOp = cloneOp;
1175	          break;
1176	        }
1177	      }
1178	    }
1179	    propagateCoreTypeUpwardForYield(defOp, coreTypeToUse);
1180	  }
1181	
1182	  return true;
1183	}
