1185	// ============================================================================
1186	// processYieldOperation: Set core_type on scf.yield and its parent scf op
1187	// ============================================================================
1188	// For each operand of scf.yield:
1189	//   - If thenYieldForElse is provided (else region of scf.if): use then yield's
1190	//     per-operand core_type as reference to determine this operand's type, and
1191	//     propagate that type upstream.
1192	//   - Otherwise (then region of scf.if, or scf.for): look at the operand's
1193	//     defining op's core_type. If it is OP_CUBE_ONLY -> "CUBE", else ->
1194	//     "VECTOR". BlockArguments without a defining op (e.g., iter_arg block
1195	//     argument) default to VECTOR.
1196	// After collecting all operand types, set ssbuffer.core_type on both the yield
1197	// op and its parent scf operation (scf.if or scf.for).
1198	void OpClassifierPass::processYieldOperation(Operation *op,
1199	                                             Operation *thenYieldForElse) {
1200	  std::vector<OpCoreType> coreTypes;
1201	
1202	  // Get the parent SCF operation (scf.if or scf.for)
1203	  Operation *parentOp = op->getParentOp();
1204	
1205	  // Process each yield operand in order
1206	  if (op->getNumOperands() > 0) {
1207	    for (unsigned i = 0; i < op->getNumOperands(); ++i) {
1208	      Value operand = op->getOperand(i);
1209	      // ---------------------------------------------------------------
1210	      // Case 1: else region yield of scf.if
1211	      // ---------------------------------------------------------------
1212	      // Use then region yield's core_type attribute to determine type.
1213	      // If then yield has a comma-separated multi-value type string (e.g.
1214	      // "CUBE,VECTOR"), extract the i-th component for this operand.
1215	      if (handleYieldFromElseRegion(coreTypes, i, thenYieldForElse, operand,
1216	                                    op)) {
1217	        continue;
1218	      }
1219	
1220	      if (Operation *defOp = operand.getDefiningOp()) {
1221	        if (CloneOpMap.count(defOp) && opCoreTypes.count(defOp) &&
1222	            opCoreTypes[defOp] == OP_CUBE_ONLY) {
1223	          Operation *cloneOp = CloneOpMap[defOp];
1224	          // Replace the operand in else yield with the cloneOp's result
1225	          for (unsigned j = 0; j < defOp->getNumResults(); ++j) {
1226	            if (defOp->getResult(j) == operand &&
1227	                j < cloneOp->getNumResults()) {
1228	              op->setOperand(i, cloneOp->getResult(j));
1229	              defOp = cloneOp;
1230	              operand = op->getOperand(i);
1231	              break;
1232	            }
1233	          }
1234	        }
1235	      }
1236	
1237	      // ---------------------------------------------------------------
1238	      // Case 2: then region yield of scf.if, or scf.for yield
1239	      // ---------------------------------------------------------------
1240	      // Determine type from the operand's defining operation:
1241	      //   - OP_CUBE_ONLY -> yield type is "CUBE"
1242	      //   - anything else (OP_UNDETERMINED, OP_VECTOR_ONLY) -> "VECTOR"
1243	      // If the operand is a BlockArgument without a defining op (e.g., an
1244	      // iter_arg that is passed through without modification), default to
1245	      // VECTOR since no compute op is associated with it.
1246	      if (Operation *def = operand.getDefiningOp()) {
1247	        OpCoreType ct = getCoreType(def);
1248	        if (ct == OP_CUBE_ONLY) {
1249	          coreTypes.push_back(OP_CUBE_ONLY);
1250	        } else {
1251	          coreTypes.push_back(OP_VECTOR_ONLY);
1252	        }
1253	      } else {
1254	        // BlockArgument (e.g., iter_arg passed through scf.for) -> VECTOR
1255	        coreTypes.push_back(OP_VECTOR_ONLY);
1256	      }
1257	    }
1258	  }
1259	
1260	  // Write ssbuffer.core_type attribute onto the yield op and its parent scf op
1261	  if (!coreTypes.empty()) {
1262	    std::string coreTypeStr = joinCoreTypes(coreTypes);
1263	    op->setAttr("ssbuffer.core_type",
1264	                StringAttr::get(op->getContext(), coreTypeStr));
1265	
1266	    OpCoreType opCt = (coreTypeStr.find("CUBE") != std::string::npos)
1267	                          ? OP_CUBE_ONLY
1268	                          : OP_VECTOR_ONLY;
1269	    opCoreTypes[op] = opCt;
1270	
1271	    if (parentOp && llvm::isa<scf::SCFDialect>(parentOp->getDialect())) {
1272	      parentOp->setAttr("ssbuffer.core_type",
1273	                        StringAttr::get(parentOp->getContext(), coreTypeStr));
1274	      opCoreTypes[parentOp] = opCt;
1275	    }
1276	  }
1277	}
1278	
1279	// ============================================================================
1280	// Step 5: Process SCF Yield Operations
1281	// ============================================================================
1282	// Entry point for yield processing. Walks all scf ops and sets core_type on
1283	// their yield terminators and on the ops themselves.
1284	// Processing order
1285	//   1. All scf.if ops: process then-region yield first (no thenYieldForElse),
1286	//      then process else-region yield (passing thenYieldForElse for type
1287	//      reference).
1288	//   2. Remaining scf.yield ops not inside scf.if (e.g., scf.for terminators).
1289	// After this step, every scf.yield and its parent scf.if/scf.for carry a
1290	// ssbuffer.core_type attribute reflecting the core_type of their result
1291	// values (derived from the defining ops of each yield operand).
1292	int OpClassifierPass::handleSCFYield() {
1293	  // Collect all scf.if operations
1294	  llvm::SmallVector<scf::IfOp> ifOps;
1295	  for (Operation *op : allOps) {
1296	    if (auto ifOp = dyn_cast<scf::IfOp>(op)) {
1297	      ifOps.push_back(ifOp);
1298	    }
1299	  }
1300	
1301	  // Process scf.if operations: first then region, then else region
1302	  for (scf::IfOp ifOp : ifOps) {
1303	    Operation *thenYield = nullptr;
1304	    if (!ifOp.getThenRegion().empty()) {
1305	      thenYield = ifOp.getThenRegion().back().getTerminator();
1306	    }
1307	
1308	    if (isa<scf::YieldOp>(thenYield)) {
1309	      processYieldOperation(thenYield, nullptr);
1310	    }
1311	
1312	    if (!ifOp.getElseRegion().empty()) {
1313	      Operation *elseYield = ifOp.getElseRegion().back().getTerminator();
1314	      if (isa<scf::YieldOp>(elseYield)) {
1315	        processYieldOperation(elseYield, thenYield);
1316	      }
1317	    }
1318	  }
1319	
1320	  // Process remaining scf.yield operations (not inside scf.if, e.g. scf.for)
1321	  for (Operation *op : allOps) {
1322	    if (!isa<scf::YieldOp>(op))
1323	      continue;
1324	
1325	    Operation *parentOp = op->getParentOp();
1326	    if (dyn_cast_or_null<scf::IfOp>(parentOp))
1327	      continue;
1328	
1329	    processYieldOperation(op, nullptr);
1330	  }
1331	
1332	  return 0;
1333	}
1334	
1335	OpCoreType OpClassifierPass::getForInitCoreType(OpOperand *operand) const {
1336	  auto forOp = llvm::dyn_cast<scf::ForOp>(operand->getOwner());
1337	  if (!forOp) {
1338	    return OP_UNDETERMINED;
1339	  }
1340	  auto iterArg = forOp.getTiedLoopRegionIterArg(operand);
1341	  if (!iterArg) {
1342	    // the result is used as lower/upper bound or step
1343	    return OP_UNDETERMINED;
1344	  }
1345	  auto sourceOperand = forOp.getTiedLoopYieldedValue(iterArg);
1346	  if (!sourceOperand) {
1347	    return OP_UNDETERMINED;
1348	  }
1349	  auto defOp = sourceOperand->get().getDefiningOp();
1350	  if (!defOp) {
1351	    // might be a blockarg, not necessary for our use-case
1352	    return OP_UNDETERMINED;
1353	  }
1354	  return getCoreType(defOp);
1355	}
1356	
1357	// ============================================================================
1358	// Step 6: CUBE_AND_VECTOR Operation Handling
1359	// ============================================================================
1360	// Problem: an operation (e.g., linalg.fill) is used by both CUBE users
1361	// (linalg.matmul) and VECTOR users (arith.addf) simultaneously.
1362	// Both cores cannot share the same op instance.
1363	// Solution: clone the op into two versions.
1364	//   - Original op  → reclassified as OP_CUBE_ONLY  → CUBE users keep using it
1365	//   - Cloned op    → classified as OP_VECTOR_ONLY → VECTOR users switched to it
1366	// Example
1367	//       shared_fill (CUBE_AND_VECTOR)
1368	//          ↑              ↑
1369	//      matmul(CUBE)   arith.addf(VECTOR)
1370	//       shared_fill (CUBE_ONLY)    → matmul (CUBE)
1371	//       shared_fill_vector_clone   → arith.addf (VECTOR)
1372	//         (VECTOR_ONLY)
1373	// This step runs after step 4 (VECTOR propagation) and before step 6
1374	// (SCF yield processing). The do-while loop handles cases where splitting
1375	// an op produces new CUBE_AND_VECTOR ops among its operands.
1376	// ============================================================================
1377	
1378	void OpClassifierPass::splitOperationForCubeAndVector(
1379	    Operation *op, llvm::DenseSet<Operation *> &processedOps,
1380	    llvm::DenseMap<Operation *, Operation *> &opToVectorClone) {
1381	  // Guard against double-processing the same op
1382	  if (processedOps.count(op))
1383	    return;
1384	  processedOps.insert(op);
1385	
1386	  // Only split ops explicitly marked CUBE_AND_VECTOR
1387	  if (opCoreTypes[op] != OP_CUBE_AND_VECTOR)
1388	    return;
1389	
1390	  // ------------------------------------------------------------------
1391	  // Phase 1: Recursively handle CUBE_AND_VECTOR operands first
1392	  // ------------------------------------------------------------------
1393	  // An operand of this op might itself be CUBE_AND_VECTOR (shared upstream).
1394	  // We must split the operand's chain before we can split this op, because
1395	  // when we build the operand mapping below, we need the VECTOR clone of
1396	  // the operand to be available. Process operands depth-first.
1397	  for (Value operand : op->getOperands()) {
1398	    if (Operation *def = operand.getDefiningOp()) {
1399	      if (opCoreTypes[def] == OP_CUBE_AND_VECTOR) {
1400	        splitOperationForCubeAndVector(def, processedOps, opToVectorClone);
1401	      }
1402	    }
1403	  }
1404	
1405	  // ------------------------------------------------------------------
1406	  // Phase 2: Build IRMapping — redirect operands to VECTOR clones
1407	  // ------------------------------------------------------------------
1408	  // When cloning this op for VECTOR users, any operand that already has
1409	  // a VECTOR clone (produced by a recursive call above) must be replaced
1410	  // with that clone so the cloned op uses the VECTOR-side values.
1411	  IRMapping mapping;
1412	  for (Value operand : op->getOperands()) {
1413	    if (Operation *def = operand.getDefiningOp()) {
1414	      auto it = opToVectorClone.find(def);
1415	      if (it != opToVectorClone.end()) {
1416	        // Operand has a VECTOR clone — use it in the cloned op
1417	        Operation *vectorClone = it->second;
1418	        for (unsigned i = 0; i < def->getNumResults(); ++i) {
1419	          if (def->getResult(i) == operand) {
1420	            mapping.map(operand, vectorClone->getResult(i));
1421	            break;
1422	          }
1423	        }
1424	      }
1425	    }
1426	  }
1427	
1428	  // ------------------------------------------------------------------
1429	  // Phase 3: Clone the op for VECTOR users
1430	  // ------------------------------------------------------------------
1431	  OpBuilder builder(op);
1432	  Operation *vectorOp = builder.clone(*op, mapping);
1433	
1434	  // Reclassify: original → CUBE_ONLY, clone → VECTOR_ONLY
1435	  opCoreTypes[op] = OP_CUBE_ONLY;
1436	  opCoreTypes[vectorOp] = OP_VECTOR_ONLY;
1437	  opToVectorClone[op] = vectorOp; // record for callers' operand mapping
1438	  allOps.push_back(vectorOp);     // track new op so it gets core_type stamped
1439	  CloneOpMap[op] = vectorOp;      // record for laterClone map
1440	  CloneOpMap[vectorOp] = op;      // record for laterClone map
1441	
1442	  // ------------------------------------------------------------------
1443	  // Phase 4: Redirect VECTOR-only users to the cloned result
1444	  // ------------------------------------------------------------------
1445	  // VECTOR users of the original result must now use the cloned result.
1446	  // CUBE users still use the original. We iterate through all result uses
1447	  // and switch VECTOR-only users over to vectorOp's corresponding result.
1448	  for (unsigned i = 0; i < op->getNumResults(); ++i) {
1449	    Value originalResult = op->getResult(i);
1450	    Value vectorResult = vectorOp->getResult(i);
1451	
1452	    llvm::SmallVector<OpOperand *> usesToUpdate;
1453	    for (OpOperand &use : originalResult.getUses()) {
1454	      Operation *user = use.getOwner();
1455	      if (!user || user == vectorOp) {
1456	        continue;
1457	      }
1458	      OpCoreType coreType = getCoreType(user);
1459	      if (llvm::isa<scf::ForOp>(user)) {
1460	        coreType = getForInitCoreType(&use);
1461	      }
1462	      if (coreType == OP_VECTOR_ONLY) {
1463	        usesToUpdate.push_back(&use);
1464	      }
1465	    }
1466	
1467	    for (OpOperand *use : usesToUpdate) {
1468	      use->set(vectorResult); // redirect to VECTOR clone
1469	    }
1470	  }
1471	}
1472	
1473	// ============================================================================
1474	// handleCubeAndVector: entry point for CUBE_AND_VECTOR splitting
1475	// ============================================================================
1476	// Repeatedly scans for CUBE_AND_VECTOR ops and splits them until no more
1477	// remain. The do-while loop is needed because splitOperationForCubeAndVector
1478	// is called recursively on operands; each recursive call may turn a
1479	// CUBE_AND_VECTOR operand into CUBE_ONLY + VECTOR_ONLY (via the same
1480	// splitOperationForCubeAndVector), which can in turn enable more splits at
1481	// the current level.
1482	
1483	int OpClassifierPass::handleCubeAndVector() {
1484	  bool changed = true;
1485	  do {
1486	    changed = false;
1487	
1488	    // Collect all ops still marked CUBE_AND_VECTOR
1489	    llvm::SmallVector<Operation *> cubeAndVectorOps;
1490	    for (Operation *op : allOps) {
1491	      if (opCoreTypes[op] == OP_CUBE_AND_VECTOR) {
1492	        cubeAndVectorOps.push_back(op);
1493	      }
1494	    }
1495	
1496	    if (cubeAndVectorOps.empty())
1497	      break;
1498	
1499	    llvm::DenseMap<Operation *, Operation *> opToVectorClone;
1500	    llvm::DenseSet<Operation *> processedOps;
1501	
1502	    for (Operation *op : cubeAndVectorOps) {
1503	      if (processedOps.count(op))
1504	        continue;
1505	      splitOperationForCubeAndVector(op, processedOps, opToVectorClone);
1506	      changed = true;
1507	    }
1508	  } while (changed);
1509	
1510	  return 0;
1511	}
1512	
1513	// ============================================================================
1514	// Step 7: Stamp Core Type to IR
1515	// ============================================================================
1516	
1517	int OpClassifierPass::stampToIR() {
1518	  for (Operation *op : allOps) {
1519	    if (!op || !op->getBlock())
1520	      continue;
1521	
1522	    auto it = opCoreTypes.find(op);
1523	    if (it == opCoreTypes.end())
1524	      continue;
1525	    OpCoreType coreType = it->second;
1526	
1527	    // Skip scf dialect operations
1528	    if (llvm::isa<scf::SCFDialect>(op->getDialect()))
1529	      continue;
1530	
1531	    // Skip linalg operations' internal block operations
1532	    Operation *parent = op->getParentOp();
1533	    bool isInsideLinalgBlock = false;
1534	    while (parent) {
1535	      if (llvm::isa<linalg::LinalgDialect>(parent->getDialect())) {
1536	        isInsideLinalgBlock = true;
1537	        break;
1538	      }
1539	      parent = parent->getParentOp();
1540	    }
1541	    if (isInsideLinalgBlock)
1542	      continue;
1543	
1544	    // Skip builtin.module, func.func, and tt.func operations
1545	    if (isa<ModuleOp, func::FuncOp>(op))
1546	      continue;
1547	
1548	    op->setAttr("ssbuffer.core_type",
1549	                StringAttr::get(op->getContext(), coreTypeToString(coreType)));
1550	  }
1551	
1552	  return 0;
1553	}
1554	
1555	// Run the pass
1556	void OpClassifierPass::runOnOperation() {
1557	  ModuleOp module = getOperation();
1558	
1559	  if (CVPipeline::hasFallbackAttr(module)) {
1560	    return;
1561	  }
1562	
1563	  LLVM_DEBUG(DBGS() << "\n--- Before Plan Compute Block  --->\n");
1564	  LLVM_DEBUG(DBGS() << module << "\n");
1565	
1566	  LLVM_DEBUG(DBGS() << "\n--- Running OpClassifierPass --->\n");
1567	
1568	  // Initialize memory dependence graph for tracking memory side effects
1569	  aliasAnalysis = std::make_shared<AliasAnalysis>(module);
1570	  memDepGraph = std::make_shared<CVPipeline::MemoryDependenceGraph>(
1571	      module, *aliasAnalysis);
1572	
1573	  // Initialize the pass
1574	  initializePass(module);
1575	
1576	  // Step 1: Pattern match around each linalg.matmul to find CUBE seeds
1577	  if (patternMatchCUBE() != 0) {
1578	    CVPipeline::setFallbackAttr(module, CVPipeline::ERRCODE_FAILED);
1579	    return;
1580	  }
1581	
1582	  // Step 2: CUBE upstream BFS from seed loads
1583	  if (propagateCubeUpstream() != 0) {
1584	    CVPipeline::setFallbackAttr(module, CVPipeline::ERRCODE_FAILED);
1585	    return;
1586	  }
1587	
1588	  // Step 3: Penetrate CUBE coloring into pure loader for-loops.
1589	  if (CVPipeline::isCubeBlockMergeEnabled() &&
1590	      penetrateCubeIntoForLoops() != 0) {
1591	    CVPipeline::setFallbackAttr(module, CVPipeline::ERRCODE_FAILED);
1592	    return;
1593	  }
1594	
1595	  // Step 4: Mark remaining operations as VECTOR
1596	  if (markRemainingAsVector() != 0) {
1597	    CVPipeline::setFallbackAttr(module, CVPipeline::ERRCODE_FAILED);
1598	    return;
1599	  }
1600	
1601	  // Step 5: VECTOR upstream BFS
1602	  if (propagateVectorUpstream() != 0) {
1603	    CVPipeline::setFallbackAttr(module, CVPipeline::ERRCODE_FAILED);
1604	    return;
1605	  }
1606	
1607	  // Step 6: Handle CUBE_AND_VECTOR operations
1608	  if (handleCubeAndVector() != 0) {
1609	    CVPipeline::setFallbackAttr(module, CVPipeline::ERRCODE_FAILED);
1610	    return;
1611	  }
1612	
1613	  // Step 7: Process SCF yield results
1614	  if (handleSCFYield() != 0) {
1615	    CVPipeline::setFallbackAttr(module, CVPipeline::ERRCODE_FAILED);
1616	    return;
1617	  }
1618	
1619	  // Step 8: Stamp to IR
1620	  if (stampToIR() != 0) {
1621	    CVPipeline::setFallbackAttr(module, CVPipeline::ERRCODE_FAILED);
1622	    return;
1623	  }
1624	
1625	  LLVM_DEBUG(DBGS() << "\n--- OpClassifierPass: end --->\n");
1626	}
1627	
1628	// Create the pass
1629	namespace mlir {
1630	namespace triton {
1631	
1632	std::unique_ptr<OperationPass<ModuleOp>> createOpClassifierPass() {
1633	  return std::make_unique<OpClassifierPass>();
1634	}
1635	
1636	void registerAddOpClassifierPasses() {
1637	  registerPass(
1638	      []() -> std::unique_ptr<mlir::Pass> { return createOpClassifierPass(); });
1639	}
1640	
1641	} // namespace triton
1642	} // namespace mlir
